/**
Fiber 很多地方用到链表（单链表），尾指针没有指向
*/
class
Update
{
constructor
(
payload, nextUpdate
)
{
this
.payload = payload;
this
.nextUpdate = nextUpdate;
// 下一个节点的指针
}
}
class
UpdateQueue
{
constructor
(
payload
)
{
this
.baseState =
null
;
// 原状态
this
.firstUpdate =
null
;
// 第一次更新
this
.lastUpdate =
null
;
// 最后一次更新
}
enqueueUpdate
(
update
)
{
if
(
this
.firstUpdate ===
null
) {
this
.firstUpdate =
this
.lastUpdate =update;
}
else
{
this
.lastUpdate.nextUpdate = update;
this
.lastUpdate = update;
}
}
// 获取老状态，遍历链表，进行更新
forceUpdate
(
)
{
let
currentState =
this
.baseState || {};
// 初始状态
let
currentUpdate =
this
.firstUpdate;
while
(currentUpdate) {
let
nextState =
typeof
currentUpdate.payload ===
'function'
? currentUpdate.payload(currentState)
: currentUpdate.payload;
currentState = {
...currentState,
...nextState,
};
// 使用当前更新得到最新的状态
currentUpdate = currentUpdate.nextUpdate;
// 找下一个节点
}
this
.firstUpdate =
this
.lastUpdate =
null
;
// 更新结束清空链表
this
.baseState = currentState;
return
currentState;
}
}
// 链表可以中断和恢复
// 每次 setState 都会通过一个链表保存起来，最后合并
// enqueueUpdate 可以类比为 setState 操作
